import{c as s,$ as i,Q as n,j as o,g as e,o as r,n as l,m as c}from"./chunks/framework.Ce_49mA8.js";const v=JSON.parse('{"title":"Analytics & Currency Basket","description":"Practical guide to personal capital analytics, currency basket protection, balancing four asset classes, and preserving financial history continuity in OmniCraft ERP.","frontmatter":{"title":"Analytics & Currency Basket","description":"Practical guide to personal capital analytics, currency basket protection, balancing four asset classes, and preserving financial history continuity in OmniCraft ERP.","datePublished":"2026-10-28","dateModified":"2026-11-19","order":20},"headers":[],"relativePath":"docs/spaces/moy-kapital/analytics.md","filePath":"docs/spaces/moy-kapital/analytics.md","lastUpdated":1795046400000}'),d={name:"docs/spaces/moy-kapital/analytics.md"},h={id:"analytics-currency-basket-strategic-wealth-control",tabindex:"-1"};function u(p,t,g,y,m,f){const a=i("DocIcon");return n(),o("div",null,[e("h1",h,[r(a,{name:"capital"}),t[0]||(t[0]=l(" Analytics & Currency Basket: Strategic Wealth Control ",-1)),t[1]||(t[1]=e("a",{class:"header-anchor",href:"#analytics-currency-basket-strategic-wealth-control","aria-label":'Permalink to "Analytics & Currency Basket: Strategic Wealth Control"'},"​",-1))]),t[2]||(t[2]=c('<p>While operational screens — such as the workshop cash flow ledger or the bank accounts registry — answer the immediate tactical question of <em>&quot;How much liquid cash is available right now?&quot;</em>, the analytical engine within the &quot;My Capital&quot; workspace resolves a fundamentally different strategic challenge. It provides the creator with a clear, long-term answer: <strong>how securely is your consolidated wealth protected against currency devaluations, inflationary shocks, and market crises, and is your family capital steadily growing year-over-year?</strong></p><p>The system provides two complementary analytical tools:</p><ul><li><strong>&quot;Capital Statistics&quot; Quick Widget:</strong> opened directly from the accounts and investments toolbar for immediate verification of currency diversification and asset fund balances;</li><li><strong>&quot;Analytics&quot; Strategic Tab:</strong> the fifth element in the top navigation funnel, dedicated to tracking multi-year net worth trajectories and monitoring household burn rate trends.</li></ul><hr><h2 id="capital-statistics-widget-asset-allocation-at-a-glance" tabindex="-1">Capital Statistics Widget: Asset Allocation at a Glance <a class="header-anchor" href="#capital-statistics-widget-asset-allocation-at-a-glance" aria-label="Permalink to &quot;Capital Statistics Widget: Asset Allocation at a Glance&quot;">​</a></h2><p>The quick statistics widget opens by clicking the analytics icon on the top toolbar of the <strong>&quot;Cash &amp; Investments&quot;</strong> tab (tooltip: <em>&quot;Capital Statistics &amp; Allocation&quot;</em>).</p><p>The widget is engineered so the craftsman can audit the allocation of their savings without interrupting active workflows:</p><div class="craft-window-frame" data-title="Capital Statistics"><div style="padding:1.25rem;"><div class="price-breakdown-card" style="margin-bottom:1.25rem;"><div class="breakdown-card-header"><span class="breakdown-badge">Currency Basket</span><h4>$48,500.00</h4></div><div class="breakdown-bar-track"><div class="breakdown-segment" style="width:64.9%;background:#3b82f6;" data-tooltip="US Dollar ($): 64.9% ($31,500.00)"></div><div class="breakdown-segment" style="width:24.7%;background:#10b981;" data-tooltip="Euro (€): 24.7% ($12,000.00)"></div><div class="breakdown-segment" style="width:10.4%;background:#f59e0b;" data-tooltip="Digital Dollar (USDT): 10.4% ($5,000.00)"></div></div><ul class="craft-feature-list" style="margin-top:0.75rem;"><li><span class="craft-list-bullet" style="background:#3b82f6;"></span><div><strong>US Dollar ($):</strong> $31,500.00 · 64.9%</div></li><li><span class="craft-list-bullet" style="background:#10b981;"></span><div><strong>Euro (€):</strong> $12,000.00 · 24.7%</div></li><li><span class="craft-list-bullet" style="background:#f59e0b;"></span><div><strong>Digital Dollar (USDT):</strong> $5,000.00 · 10.4%</div></li></ul></div><div class="price-breakdown-card"><div class="breakdown-card-header"><span class="breakdown-badge">Asset Classes</span><h4>$94,000.00</h4></div><div class="breakdown-bar-track"><div class="breakdown-segment" style="width:38.8%;background:#06b6d4;" data-tooltip="Accounts &amp; Wallets: 38.8% ($36,500.00)"></div><div class="breakdown-segment" style="width:12.8%;background:#8b5cf6;" data-tooltip="Investment Portfolio: 12.8% ($12,000.00)"></div><div class="breakdown-segment" style="width:25.5%;background:#f59e0b;" data-tooltip="Personal Property: 25.5% ($24,000.00)"></div><div class="breakdown-segment" style="width:22.9%;background:#3b82f6;" data-tooltip="Workshop Capital: 22.9% ($21,500.00)"></div></div><ul class="craft-feature-list" style="margin-top:0.75rem;"><li><span class="craft-list-bullet" style="background:#06b6d4;"></span><div><strong>Accounts &amp; Wallets:</strong> $36,500.00 · 38.8%</div></li><li><span class="craft-list-bullet" style="background:#8b5cf6;"></span><div><strong>Investment Portfolio:</strong> $12,000.00 · 12.8%</div></li><li><span class="craft-list-bullet" style="background:#f59e0b;"></span><div><strong>Personal Property:</strong> $24,000.00 · 25.5%</div></li><li><span class="craft-list-bullet" style="background:#3b82f6;"></span><div><strong>Workshop Capital:</strong> $21,500.00 · 22.9%</div></li></ul></div></div></div><h3 id="display-modes-side-drawer-or-centered-modal-dialog" tabindex="-1">Display Modes: Side Drawer or Centered Modal Dialog <a class="header-anchor" href="#display-modes-side-drawer-or-centered-modal-dialog" aria-label="Permalink to &quot;Display Modes: Side Drawer or Centered Modal Dialog&quot;">​</a></h3><p>The interface adapts to your workspace layout. In the <strong>&quot;Workspace Settings&quot;</strong> dialog (gear icon on the toolbar), you can choose your preferred widget format:</p><ul class="craft-feature-list"><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><rect width="18" height="18" x="3" y="3" rx="2"></rect><path d="M15 3v18"></path></svg></span><span><strong>Side Navigation Drawer (Default):</strong> The panel smoothly slides in from the right edge of the screen at a fixed width without obscuring your account lists and investment tables. This is well-suited for widescreen monitors, allowing you to audit currency shares while simultaneously allocating deposits. Close it by clicking the close icon or outside the drawer.</span></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><rect width="18" height="18" x="3" y="3" rx="2"></rect><path d="M9 9h6v6H9z"></path></svg></span><span><strong>Centered Modal Dialog:</strong> A focused 520×520 pixel modal window positioned directly in the center of the display. Ideal for deliberate balance audits before closing an accounting period or committing to significant capital purchases.</span></li></ul><div class="info custom-block"><p class="custom-block-title">Safe Handling of Empty States</p><p>If the system contains no accounts with non-zero balances and connected workshop databases are empty, the widget displays an informative fallback notice: <em>&quot;Not enough data to calculate statistics&quot;</em>. Real-time calculations activate automatically as soon as initial balances are entered.</p></div><hr><h2 id="currency-basket-allocation-protecting-capital-against-devaluation" tabindex="-1">Currency Basket Allocation: Protecting Capital Against Devaluation <a class="header-anchor" href="#currency-basket-allocation-protecting-capital-against-devaluation" aria-label="Permalink to &quot;Currency Basket Allocation: Protecting Capital Against Devaluation&quot;">​</a></h2><p>Rapid inflation and foreign exchange volatility can erode workshop profit in a matter of weeks. To prevent silent losses, OmniCraft ERP continuously recalculates your <strong>Currency Basket</strong>.</p><p>The algorithm scans every active (non-archived) account in the &quot;Accounts &amp; Wallets&quot; subtab along with open positions in your investment portfolio:</p><div class="formula-hero-card"><div class="formula-card-top"><span class="formula-badge">Currency Basket Algorithm</span><div class="formula-heading">Calculating Currency Share in Liquid Wealth</div></div><div class="formula-equation-box"><div class="math-formula-display"><span class="math-var">Currency Share (%)</span><span class="math-op">=</span><span class="math-group">(</span><span class="math-var">Native Balance</span><span class="math-op">×</span><span class="math-var">Exchange Rate</span><span class="math-group">)</span><span class="math-op">/</span><span class="math-var">Total Liquid Pool</span><span class="math-op">×</span><span class="math-num">100%</span></div></div><div class="formula-card-bottom"><p>The total liquid pool includes balances across all checking accounts, deposits, cash reserves, and current investment valuations converted into the base accounting currency using active exchange rates.</p></div></div><h3 id="multi-segment-stacked-bar" tabindex="-1">Multi-Segment Stacked Bar <a class="header-anchor" href="#multi-segment-stacked-bar" aria-label="Permalink to &quot;Multi-Segment Stacked Bar&quot;">​</a></h3><p>At the top of the section, an interactive multi-segment stacked bar visualizes currency weights. Each segment represents a distinct currency, with width precisely proportional to its share in the liquid pool.</p><p>Hovering over any segment displays an informative tooltip showing exact base currency amounts and percentage shares.</p><h3 id="detailed-currency-ledger" tabindex="-1">Detailed Currency Ledger <a class="header-anchor" href="#detailed-currency-ledger" aria-label="Permalink to &quot;Detailed Currency Ledger&quot;">​</a></h3><p>Below the visual bar, the system generates a sorted ledger of currency holdings:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Ledger Column</th><th style="text-align:left;">Rendered Metric</th><th style="text-align:left;">Operational Value for the Craftsman</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Currency Title</strong></td><td style="text-align:left;">Official localized title and currency symbol (e.g., <em>&quot;US Dollar ($)&quot;</em>)</td><td style="text-align:left;">Generated strictly using international Unicode Babel standards without ambiguous abbreviations.</td></tr><tr><td style="text-align:left;"><strong>Base Equivalent</strong></td><td style="text-align:left;">Total valuation in your primary workshop currency (e.g., <em>&quot;$ 31,500.00&quot;</em>)</td><td style="text-align:left;">Reflects the real purchasing power of that currency holding in your local operating market.</td></tr><tr><td style="text-align:left;"><strong>Native &amp; Weight</strong></td><td style="text-align:left;">Original nominal balance and portfolio share (e.g., <em>&quot;€ 10,200.00 · 24.7%&quot;</em>)</td><td style="text-align:left;">Enables continuous monitoring of foreign account holdings and exposure levels.</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Golden Rule of Craft Diversification</p><p>A seasoned workshop master structures liquid reserves across three distinct tiers:</p><ol><li><strong>Operational Tier (1–2 months of shop expenses):</strong> held strictly in the primary currency required by raw material and hardware vendors to ensure seamless inventory replenishment;</li><li><strong>Family Safety Cushion (3–6 months of living expenses):</strong> maintained in stable, highly liquid currencies and yield-bearing cash deposits;</li><li><strong>Growth Capital:</strong> distributed between high-efficiency production equipment and a diversified investment portfolio.</li></ol></div><hr><h2 id="four-asset-classes-balancing-long-term-stability" tabindex="-1">Four Asset Classes: Balancing Long-Term Stability <a class="header-anchor" href="#four-asset-classes-balancing-long-term-stability" aria-label="Permalink to &quot;Four Asset Classes: Balancing Long-Term Stability&quot;">​</a></h2><p>While the currency basket analyzes liquid money and securities, the <strong>&quot;Asset Classes&quot;</strong> panel provides a complete management balance sheet. It categorizes your consolidated net worth into four foundational asset pillars:</p><ul class="craft-feature-list"><li><span class="craft-list-bullet"></span><div><strong>Liquid Accounts (Teal):</strong><br> Checking accounts, high-yield deposits, digital wallets, and cash reserves. </div></li><li><span class="craft-list-bullet"></span><div><strong>Investments (Violet):</strong><br> Bonds, equities, index funds, peer loans, and digital assets. </div></li><li><span class="craft-list-bullet"></span><div><strong>Personal Property (Amber):</strong><br> Real estate, land, and vehicles weighted strictly by personal ownership share. </div></li><li><span class="craft-list-bullet"></span><div><strong>Workshop Capital (Blue):</strong><br> Clean commercial net tangible assets across active production shops and studios. </div></li></ul><h3 id="net-worth-valuation-and-class-weight-formula" tabindex="-1">Net Worth Valuation and Class Weight Formula <a class="header-anchor" href="#net-worth-valuation-and-class-weight-formula" aria-label="Permalink to &quot;Net Worth Valuation and Class Weight Formula&quot;">​</a></h3><p>The program reconciles each asset category against total consolidated capital:</p><div class="formula-hero-card"><div class="formula-card-top"><span class="formula-badge">Balance Sheet Allocation</span><div class="formula-heading">Calculating Asset Class Weights</div></div><div class="formula-equation-box"><div class="math-formula-display"><span class="math-var">Fund Share (%)</span><span class="math-op">=</span><span class="math-var">Class Book Value</span><span class="math-op">/</span><span class="math-var">Consolidated Net Worth</span><span class="math-op">×</span><span class="math-num">100%</span></div></div><div class="formula-card-bottom"><p>Consolidated Net Worth = Liquid Accounts + Investments + Personal Property + Active Workshop Assets. Workshop valuation includes cash on hand, raw material inventory calculated via Moving Average Cost (MAC), finished goods via First-In, First-Out (FIFO), and machinery book value net of linear depreciation.</p></div></div><h3 id="roles-and-balance-functions-of-the-four-pillars" tabindex="-1">Roles and Balance Functions of the Four Pillars <a class="header-anchor" href="#roles-and-balance-functions-of-the-four-pillars" aria-label="Permalink to &quot;Roles and Balance Functions of the Four Pillars&quot;">​</a></h3><p>Each asset class serves a distinct strategic purpose in insulating the creator from economic and operational hazards:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Asset Class</th><th style="text-align:left;">Palette Color</th><th style="text-align:left;">Primary Function in Portfolio</th><th style="text-align:left;">Vulnerability if Imbalanced</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Accounts &amp; Wallets</strong></td><td style="text-align:left;">Teal (<code>Teal</code>)</td><td style="text-align:left;">Instant liquidity, emergency expense coverage, vendor payments.</td><td style="text-align:left;">Excess leads to silent cash drag from inflation; deficiency triggers liquidity crunches.</td></tr><tr><td style="text-align:left;"><strong>Investment Portfolio</strong></td><td style="text-align:left;">Violet (<code>Violet</code>)</td><td style="text-align:left;">Beating inflation, passive compounding, capital growth above baseline rates.</td><td style="text-align:left;">Excess risks portfolio drawdowns during downturns; illiquidity in emergencies.</td></tr><tr><td style="text-align:left;"><strong>Personal Property</strong></td><td style="text-align:left;">Amber (<code>Amber</code>)</td><td style="text-align:left;">Long-term tangible safety anchor for the family (residence, vehicles, land).</td><td style="text-align:left;">Low liquidity: physical real estate cannot be converted into cash in a single day.</td></tr><tr><td style="text-align:left;"><strong>Workshop Capital</strong></td><td style="text-align:left;">Blue (<code>Blue</code>)</td><td style="text-align:left;">Engine of operational cash flow, productive machinery, skilled labor output.</td><td style="text-align:left;">Concentration risk: a downturn in one craft segment jeopardizes family security.</td></tr></tbody></table><hr><h2 id="analytics-tab-long-term-trends-and-strategic-benchmarks" tabindex="-1">&quot;Analytics&quot; Tab: Long-Term Trends and Strategic Benchmarks <a class="header-anchor" href="#analytics-tab-long-term-trends-and-strategic-benchmarks" aria-label="Permalink to &quot;&quot;Analytics&quot; Tab: Long-Term Trends and Strategic Benchmarks&quot;">​</a></h2><p>While the quick statistics widget captures current balances, the dedicated <strong>&quot;Analytics&quot;</strong> tab (the fifth button in the top navigation funnel of &quot;My Capital&quot;) is engineered for strategic trend analysis.</p><p>The tab header presents the title <strong>&quot;Analytics and Trends&quot;</strong>, a roadmap progress indicator (<em>&quot;Coming in upcoming releases&quot;</em>), and a documentation reference button.</p><p>Three strategic preview cards anchor the screen:</p><table class="craft-matrix-table"><thead><tr><th style="width:34%;">Net Worth Dynamics</th><th style="width:33%;">Asset Allocation</th><th style="width:33%;">Free Spending Trends (Burn Rate)</th></tr></thead><tbody><tr><td><strong>Annual Trend: +24.8%</strong><br>Continuous monthly history tracking.</td><td><strong>4 Asset Classes</strong><br>Balanced ratio of cash, investments, and shops.</td><td><strong>Via Balance Delta</strong><br>Automated lifestyle expense tracking without receipts.</td></tr></tbody></table><ol><li><strong>&quot;Net Worth Dynamics&quot; Card:</strong><ul><li>Tracks monthly net worth expansion over multi-year operational horizons;</li><li>Calculates compound annual growth rate with an emerald <code>+</code> indicator;</li><li>Demonstrates whether operational gains outpace actual cost inflation.</li></ul></li><li><strong>&quot;Asset Allocation&quot; Card:</strong><ul><li>Audits diversification balance across the four core asset classes;</li><li>Prevents over-concentration in heavy machinery at the expense of liquid cash.</li></ul></li><li><strong>&quot;Free Spending Trends&quot; Card:</strong><ul><li>Tracks average monthly household lifestyle burn rate;</li><li>Derived automatically via mathematical balance deltas: workshop profits plus external earnings minus net capital change and major recorded expenses, eliminating manual receipt entry.</li></ul></li></ol><h3 id="empty-state-protection" tabindex="-1">Empty State Protection <a class="header-anchor" href="#empty-state-protection" aria-label="Permalink to &quot;Empty State Protection&quot;">​</a></h3><p>When launching OmniCraft ERP in a fresh environment without existing transaction history, the tab displays an onboarding empty state:</p><ul><li>A clear explanatory summary detailing the purpose of long-term analytics;</li><li>An <strong>&quot;+ Add Account&quot;</strong> button to jump-start financial tracking with an initial bank account or cash reserve;</li><li>A sample data generator option allowing new creators to explore charts and metrics on simulated craft business figures.</li></ul><hr><h2 id="financial-history-continuity-architectural-law-stage-m5" tabindex="-1">Financial History Continuity: Architectural Law (Stage M5) <a class="header-anchor" href="#financial-history-continuity-architectural-law-stage-m5" aria-label="Permalink to &quot;Financial History Continuity: Architectural Law (Stage M5)&quot;">​</a></h2><p>One of the most frustrating flaws of conventional accounting software is data loss when restructuring business units. When an artisan sells a woodwork division or discontinues a repair services branch and deletes that workspace, standard tools lose historical records: multi-year profit charts collapse, and financial trajectories become fragmented.</p><p>OmniCraft ERP enforces the <strong>architectural invariant of financial history continuity (Stage M5)</strong>.</p><div class="info custom-block"><p class="custom-block-title">Financial History Continuity (Stage M5)</p><p>OmniCraft ERP automatically records monthly snapshots of your workshops. Even when closing or deleting an old workspace, historical charts preserve every month.</p></div><h3 id="how-historical-snapshot-preservation-operates" tabindex="-1">How Historical Snapshot Preservation Operates <a class="header-anchor" href="#how-historical-snapshot-preservation-operates" aria-label="Permalink to &quot;How Historical Snapshot Preservation Operates&quot;">​</a></h3><ul class="craft-feature-list"><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"></circle><polyline points="12 6 12 12 16 14"></polyline></svg></span><span><strong>Automated Monthly Snapshots:</strong> At the conclusion of each accounting period, the system logs consolidated balance snapshots capturing workshop assets and net profit.</span></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"></path><polyline points="7 10 12 15 17 10"></polyline><line x1="12" x2="12" y1="15" y2="3"></line></svg></span><span><strong>Isolation from Workspace Deletion:</strong> If a workspace is decommissioned and deleted from disk, all accumulated monthly snapshots are preserved inside the central database of &quot;My Capital&quot;.</span></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><polyline points="23 6 13.5 15.5 8.5 10.5 1 18"></polyline><polyline points="17 6 23 6 23 12"></polyline></svg></span><span><strong>Unbroken Net Worth Trajectory:</strong> Multi-year wealth trajectories spanning 3, 5, or 10 years remain continuous. The program accurately accounts for every dollar generated, regardless of corporate or workspace restructuring.</span></li></ul><div class="info custom-block"><p class="custom-block-title">Safe Workspace Archiving</p><p>When removing a workspace via workspace management, the system performs a final net asset audit before archiving. All completed calculations remain permanently archived in your family wealth trajectory.</p></div><hr><h2 id="balance-sheet-diagnostics-workshop-health-check" tabindex="-1">Balance Sheet Diagnostics: Workshop Health Check <a class="header-anchor" href="#balance-sheet-diagnostics-workshop-health-check" aria-label="Permalink to &quot;Balance Sheet Diagnostics: Workshop Health Check&quot;">​</a></h2><p>Auditing the statistics widget periodically reveals early indicators of business strain:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Diagnostic Indicator</th><th style="text-align:left;">Structural Vulnerability</th><th style="text-align:left;">Recommended Master Action</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Workshop Capital &gt; 70%, Liquid Cash &lt; 5%</strong></td><td style="text-align:left;">&quot;Frozen Workshop&quot;. Capital is trapped in tons of raw timber, leather, or machinery. A minor invoice delay from a client could trigger a payroll crisis.</td><td style="text-align:left;">Temporarily freeze advance raw material purchases, discount aging finished stock, replenish liquid cash reserves.</td></tr><tr><td style="text-align:left;"><strong>Currency Basket: 100% Single Currency</strong></td><td style="text-align:left;">Severe exchange rate vulnerability. If equipment parts or supplies originate abroad, currency devaluation will make replenishment unprofitable.</td><td style="text-align:left;">Diversify operating profits into vendor procurement currencies (USD, EUR, stable digital assets).</td></tr><tr><td style="text-align:left;"><strong>Investments &gt; 50% Without Emergency Fund</strong></td><td style="text-align:left;">Over-extended portfolio risk. Unforeseen personal or family expenses will force liquidation of assets during market drawdowns.</td><td style="text-align:left;">Establish an untouchable liquid reserve in high-yield, instant-access bank accounts.</td></tr><tr><td style="text-align:left;"><strong>Personal Property &gt; 80%</strong></td><td style="text-align:left;">Low asset mobility. Capital is tied up in illiquid physical real estate or personal vehicles generating no operating cash flow.</td><td style="text-align:left;">Expand productive workshop capacity to increase ongoing operational earnings.</td></tr></tbody></table><hr><h2 id="frequently-asked-questions" tabindex="-1">Frequently Asked Questions <a class="header-anchor" href="#frequently-asked-questions" aria-label="Permalink to &quot;Frequently Asked Questions&quot;">​</a></h2><h3 id="how-frequently-does-the-program-refresh-statistical-metrics" tabindex="-1">How frequently does the program refresh statistical metrics? <a class="header-anchor" href="#how-frequently-does-the-program-refresh-statistical-metrics" aria-label="Permalink to &quot;How frequently does the program refresh statistical metrics?&quot;">​</a></h3><p>The currency basket and asset class allocations recalculate dynamically each time you open the widget or slide drawer. The system retrieves real-time balances, active exchange rates, and current workshop values directly from local databases.</p><h3 id="what-happens-when-currency-exchange-rates-change" tabindex="-1">What happens when currency exchange rates change? <a class="header-anchor" href="#what-happens-when-currency-exchange-rates-change" aria-label="Permalink to &quot;What happens when currency exchange rates change?&quot;">​</a></h3><p>When you update exchange rates in the <strong>&quot;Exchange Rates&quot;</strong> dialog (bidirectional arrow button on the toolbar), all base currency equivalents for foreign accounts and assets update immediately. Relative portfolio shares in the currency basket adjust dynamically.</p><h3 id="are-liabilities-and-debts-factored-into-asset-classes" tabindex="-1">Are liabilities and debts factored into asset classes? <a class="header-anchor" href="#are-liabilities-and-debts-factored-into-asset-classes" aria-label="Permalink to &quot;Are liabilities and debts factored into asset classes?&quot;">​</a></h3><p>Yes. Outstanding liabilities or negative credit card balances reduce the net liquid cash total. In commercial workshops, accounts payable to suppliers similarly decrease the net asset valuation of that workspace.</p>',64))])}const k=s(d,[["render",u]]);export{v as __pageData,k as default};
